namespace ConsentSyncCore.Services.Eligibility;

/// <summary>Read-only description of an administrative eligibility rule shown in the Criteria Explorer.</summary>
public sealed record EligibilityCriterionDefinition(
    string AppointmentMilestone,
    string MinAge,
    string MaxAge,
    string RequiredInterval,
    string MissingPhisHistoryAction,
    string ClinicalLogicManagementSummary,
    string CalculationExplanation,
    string FrenchCalculationExplanation);

